function fail(code){throw new Error(code);}
function sha256(bytes){return crypto.createHash('sha256').update(bytes).digest('hex');}
function count(haystack,needle){return String(haystack).split(needle).length-1;}
function oneAnchor(source,re,code){
  const m=source.match(re);if(!m||m.length<1)fail(code+'_anchor_missing');
  const all=[...source.matchAll(new RegExp(re.source,re.flags.includes('g')?re.flags:re.flags+'g'))];
  if(all.length!==1)fail(code+'_anchor_nonunique');return m;
}
function ensureAbsentOrOnce(source,needle){const n=count(source,needle);if(n>1)fail('action_duplicate');return n===1;}
