function buildTypedScope(){return Object.freeze({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});}
function buildBaseRegistration(source){
  source=String(source);if(ensureAbsentOrOnce(source,ACTION))return source;
  const re=/const HOST_ACTION_V2_SPECS\s*=\s*Object\.freeze\(\{/;
  const m=oneAnchor(source,re,'base_specs');
  const entry=`\n  ${ACTION}: { operation: '${OPERATION}', rollback: 'host-action-v2:control-plane-current-owner-binding-refresh-v1:exact-preimage' },`;
  const out=source.slice(0,m.index+m[0].length)+entry+source.slice(m.index+m[0].length);
  const l3=/const HOST_ACTION_V2_LEVEL3\s*=\s*new Set\((\[[\s\S]*?\])\);/.exec(out);
  if(!l3)fail('base_level3_anchor_missing');if(l3[1].includes(ACTION))fail('base_level3_contains_current_owner_refresh');
  return out;
}
function buildExecutorRegistration(source){
  source=String(source);if(ensureAbsentOrOnce(source,ACTION))return source;
  const specRe=/const HOST_ACTION_V2_SPECS\s*=\s*(?:Object\.freeze\()?\{/;
  const sm=oneAnchor(source,specRe,'executor_specs');
  const specEntry=`\n  ${ACTION}:{operation:'${OPERATION}',kind:'${ACTION}'},`;
  let out=source.slice(0,sm.index+sm[0].length)+specEntry+source.slice(sm.index+sm[0].length);
  const dispatch='applyHostActionV2=async function(action){';
  if(count(out,dispatch)!==1)fail('executor_dispatch_anchor_nonunique');
  const helper=`const CURRENT_OWNER_BINDING_REFRESH_HELPER='${ACTION_PATH}';\nconst CURRENT_OWNER_BINDING_REFRESH_RESULT='/var/lib/prhm-agent-selfmaint-exec/current-owner-binding-v1/result.json';\nfunction applyControlPlaneCurrentOwnerBindingRefreshV1(){\n  if(!fs.existsSync(CURRENT_OWNER_BINDING_REFRESH_HELPER))throw new Error('current_owner_binding_refresh_helper_missing');\n  try{if(fs.existsSync(CURRENT_OWNER_BINDING_REFRESH_RESULT))fs.unlinkSync(CURRENT_OWNER_BINDING_REFRESH_RESULT)}catch{}\n  const unit='prhm-current-owner-binding-refresh-v1-'+Date.now();\n  const args=['--wait','--collect','--unit='+unit,${EXECUTOR_SYSTEMD_PROPERTIES.map(x=>`'--property=${x}'`).join(',')},'--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',CURRENT_OWNER_BINDING_REFRESH_HELPER,'--apply'];\n  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:900000});\n  const result=readJson(CURRENT_OWNER_BINDING_REFRESH_RESULT);\n  if(result.ok!==true||result.action!=='${ACTION}'||result.production_application_mutation!==false||result.database_mutation!==false||result.titan_cutover!==false||result.rollback_performed!==false)throw new Error('current_owner_binding_refresh_result_invalid');\n  return result;\n}\n`;
  out=out.replace(dispatch,helper+dispatch+`if(action==='${ACTION}')return applyControlPlaneCurrentOwnerBindingRefreshV1();`);
  return out;
}
function buildMcpRegistration(source){
  source=String(source);if(ensureAbsentOrOnce(source,ACTION))return source;
  const re=/const HostActionV2\s*=\s*z\.enum\(\[([\s\S]*?)\]\);/;
  const m=oneAnchor(source,re,'mcp_enum');
  const body=m[1].trimEnd(),joined=body+(body.trim().endsWith(',')?'':',')+`'${ACTION}'`;
  return source.slice(0,m.index)+`const HostActionV2=z.enum([${joined}]);`+source.slice(m.index+m[0].length);
}
function buildPolicySourceRegistration(source){
  source=String(source);if(ensureAbsentOrOnce(source,ACTION))return source;
  let obj;try{obj=JSON.parse(source);}catch{fail('policy_json_invalid');}
  if(!obj.operations||typeof obj.operations!=='object'||Array.isArray(obj.operations))fail('policy_operations_missing');
  if(!Array.isArray(obj.typed_scopes))fail('policy_typed_scopes_missing');
  if(obj.operations[OPERATION])fail('policy_operation_duplicate');
  if(obj.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_scope_duplicate');
  const p=buildPolicyRegistration();
  obj.operations[OPERATION]={level:p.level,risk:p.risk,requires_second_confirmation:p.requires_second_confirmation,one_time_use:p.one_time_use,requested_approver:p.requested_approver,expires_seconds:p.expires_seconds,policy_version:p.policy_version,rollback_reference:p.rollback_reference};
  obj.typed_scopes.push(buildTypedScope());
  return JSON.stringify(obj,null,2)+'\n';
}
function buildRegistrationCandidates(live){
  if(!live||typeof live!=='object')fail('live_sources_invalid');
  for(const k of Object.keys(TARGETS)){
    if(typeof live[k]!=='string')fail('live_source_missing:'+k);
    if(sha256(Buffer.from(live[k]))!==LIVE_PINS[k])fail('live_pin_mismatch:'+k);
  }
  return Object.freeze({
    base:buildBaseRegistration(live.base),
    executor:buildExecutorRegistration(live.executor),
    policy:buildPolicySourceRegistration(live.policy),
    mcp:buildMcpRegistration(live.mcp)
  });
}
function embeddedModules(){
  const out={};
  for(const [name,spec] of Object.entries(MODULE_INSTALLS)){
    const source=EMBEDDED_MODULE_SOURCE[name];
    if(typeof source!=='string')fail('embedded_module_missing:'+name);
    const bytes=Buffer.from(source,'utf8');
    if(sha256(bytes)!==spec.sha256)fail('embedded_module_sha_mismatch:'+name);
    out[name]=bytes;
  }
  return out;
}
function regular(file){
  const st=fs.lstatSync(file);
  if(st.isSymbolicLink()||!st.isFile()||fs.realpathSync(file)!==file)fail('not_regular:'+file);
  return st;
}
function readLive(){
  const source={},meta={};
  for(const [k,file] of Object.entries(TARGETS)){
    const st=regular(file),bytes=fs.readFileSync(file),actual=sha256(bytes);
    if(actual!==LIVE_PINS[k])fail('live_pin_mismatch:'+k+':'+actual);
    source[k]=bytes.toString('utf8');
    meta[k]={st,bytes,sha256:actual};
  }
  return {source,meta};
}
function nodeBin(){return fs.existsSync('/usr/local/bin/prhm-node')?'/usr/local/bin/prhm-node':process.execPath;}
function syntaxBytes(bytes,kind,label){
  const ext=kind==='json'?'.json':kind==='mjs'?'.mjs':'.js';
  const p='/tmp/prhm-current-owner-v31-'+label+'-'+process.pid+'-'+Date.now()+ext;
  try{
    fs.writeFileSync(p,bytes,{flag:'wx',mode:0o600});
    if(kind==='json'){JSON.parse(bytes.toString('utf8'));return;}
    const r=cp.spawnSync(nodeBin(),['--check',p],{encoding:'utf8',timeout:30000,maxBuffer:500000});
    if(r.error||r.status!==0)fail('syntax_failed:'+label+':'+String(r.stderr||r.stdout||r.error?.message||'').slice(-500));
  }finally{try{fs.unlinkSync(p);}catch{}}
}
function prepare(){
  const live=readLive(),modules=embeddedModules(),candidates=buildRegistrationCandidates(live.source);
  for(const [name,bytes] of Object.entries(modules))syntaxBytes(bytes,'js','module-'+name);
  syntaxBytes(Buffer.from(candidates.base),'js','base');
  syntaxBytes(Buffer.from(candidates.executor),'js','executor');
  syntaxBytes(Buffer.from(candidates.mcp),'mjs','mcp');
  syntaxBytes(Buffer.from(candidates.policy),'json','policy');
  const candidateSha=Object.fromEntries(Object.entries(candidates).map(([k,v])=>[k,sha256(Buffer.from(v))]));
  const moduleSha=Object.fromEntries(Object.entries(modules).map(([k,v])=>[k,sha256(v)]));
  return {live,modules,candidates,candidateSha,moduleSha};
}
function selftest(){
  const modules=embeddedModules();
  const base="const HOST_ACTION_V2_SPECS = Object.freeze({});\nconst HOST_ACTION_V2_LEVEL3 = new Set([]);\n";
  const executor="const HOST_ACTION_V2_SPECS={};\napplyHostActionV2=async function(action){return applyHostActionV2Original(action);};\n";
  const mcp="const HostActionV2=z.enum(['existing']);\n";
  const policy=JSON.stringify({operations:{existing:{level:3}},typed_scopes:[{action:'existing'}]});
  buildBaseRegistration(base);buildExecutorRegistration(executor);buildMcpRegistration(mcp);buildPolicySourceRegistration(policy);
  return {ok:true,action:INSTALLER_ACTION,version:VERSION,selftest_only:true,module_sha256:Object.fromEntries(Object.entries(modules).map(([k,v])=>[k,sha256(v)])),production_mutation:false,production_application_mutation:false,database_mutation:false};
}
function preflight(){
  const p=prepare();
  return {ok:true,action:INSTALLER_ACTION,version:VERSION,target_action:ACTION,preflight_only:true,live_pins:{...LIVE_PINS},candidate_sha256:p.candidateSha,module_sha256:p.moduleSha,services:[...SERVICES],production_mutation:false,production_application_mutation:false,database_mutation:false,titan_cutover:false};
}
function atomicWrite(file,bytes,meta){
  fs.mkdirSync(path.dirname(file),{recursive:true,mode:0o755});
  const tmp=file+'.v31-'+process.pid+'-'+Date.now()+'.tmp';
  let fd;
  try{
    fd=fs.openSync(tmp,'wx',meta.mode);fs.writeFileSync(fd,bytes);fs.fsyncSync(fd);fs.closeSync(fd);fd=undefined;
    fs.chownSync(tmp,meta.uid,meta.gid);fs.chmodSync(tmp,meta.mode);fs.renameSync(tmp,file);
    const dfd=fs.openSync(path.dirname(file),fs.constants.O_RDONLY|fs.constants.O_DIRECTORY);try{fs.fsyncSync(dfd);}finally{fs.closeSync(dfd);}
  }catch(error){try{if(fd!==undefined)fs.closeSync(fd);}catch{}try{fs.unlinkSync(tmp);}catch{}throw error;}
}
function snapshotPath(file){
  try{
    const st=regular(file),bytes=fs.readFileSync(file);
    return {file,exists:true,bytes,sha256:sha256(bytes),uid:st.uid,gid:st.gid,mode:st.mode&0o7777};
  }catch(error){
    if(error.code==='ENOENT')return {file,exists:false};
    throw error;
  }
}
function backupSnapshot(dir,record){
  const key=sha256(Buffer.from(record.file)).slice(0,24);
  const meta={file:record.file,exists:record.exists,sha256:record.sha256||null,uid:record.uid??null,gid:record.gid??null,mode:record.mode??null};
  fs.writeFileSync(path.join(dir,key+'.json'),JSON.stringify(meta,null,2)+'\n',{flag:'wx',mode:0o600});
  if(record.exists)fs.writeFileSync(path.join(dir,key+'.bin'),record.bytes,{flag:'wx',mode:0o600});
  return {...record,backup_key:key};
}
function restartServices(){
  for(const service of SERVICES){
    const r=cp.spawnSync('/usr/bin/systemctl',['restart',service],{encoding:'utf8',timeout:90000,maxBuffer:500000});
    if(r.error||r.status!==0)fail('service_restart_failed:'+service);
  }
  for(const service of SERVICES){
    const r=cp.spawnSync('/usr/bin/systemctl',['is-active',service],{encoding:'utf8',timeout:20000,maxBuffer:50000});
    if(r.error||r.status!==0||String(r.stdout).trim()!=='active')fail('service_not_active:'+service);
  }
}
function apply(){
  if(process.getuid&&process.getuid()!==0)fail('root_required');
  const p=prepare();
  const stamp=new Date().toISOString().replace(/[:.]/g,'-');
  const backupDir=path.join(BACKUP_ROOT,stamp+'-'+process.pid);
  fs.mkdirSync(backupDir,{recursive:true,mode:0o700});
  const paths=[...Object.values(MODULE_INSTALLS).map(x=>x.destination_path),...Object.values(TARGETS)];
  const snapshots=new Map(paths.map(file=>[file,backupSnapshot(backupDir,snapshotPath(file))]));
  const mutated=[];
  try{
    for(const [name,spec] of Object.entries(MODULE_INSTALLS)){
      const file=spec.destination_path,old=snapshots.get(file),meta=old.exists?{uid:old.uid,gid:old.gid,mode:spec.mode}:{uid:0,gid:0,mode:spec.mode};
      atomicWrite(file,p.modules[name],meta);mutated.push(file);
      if(sha256(fs.readFileSync(file))!==spec.sha256)fail('module_postwrite_sha_mismatch:'+name);
    }
    for(const [k,file] of Object.entries(TARGETS)){
      const old=snapshots.get(file),bytes=Buffer.from(p.candidates[k],'utf8');
      atomicWrite(file,bytes,{uid:old.uid,gid:old.gid,mode:old.mode});mutated.push(file);
      if(sha256(fs.readFileSync(file))!==p.candidateSha[k])fail('registration_postwrite_sha_mismatch:'+k);
    }
    restartServices();
    const result={ok:true,schema_version:'prhm.current-owner-binding-registration.v31',action:INSTALLER_ACTION,target_action:ACTION,installed:true,backup_dir:backupDir,post_install_sha256:p.candidateSha,module_sha256:p.moduleSha,services:[...SERVICES],production_mutation:true,control_plane_mutation:true,production_application_mutation:false,database_mutation:false,titan_cutover:false,rollback_performed:false};
    fs.mkdirSync(path.dirname(RESULT),{recursive:true,mode:0o700});fs.writeFileSync(RESULT,JSON.stringify(result,null,2)+'\n',{mode:0o600});
    return result;
  }catch(error){
    const errors=[];
    for(const file of [...mutated].reverse()){
      const old=snapshots.get(file);
      try{
        if(old.exists)atomicWrite(file,old.bytes,{uid:old.uid,gid:old.gid,mode:old.mode});
        else try{fs.unlinkSync(file);}catch(e){if(e.code!=='ENOENT')throw e;}
      }catch(e){errors.push(file+':'+String(e&&e.message||e));}
    }
    try{restartServices();}catch(e){errors.push('restart:'+String(e&&e.message||e));}
    if(errors.length)fail('install_failed_rollback_failed:'+String(error&&error.message||error)+':'+errors.join('|'));
    fail('install_failed_rolled_back:'+String(error&&error.message||error));
  }
}
function contract(){return Object.freeze({schema_version:'prhm.current-owner-binding-registration.v31.contract',installer_action:INSTALLER_ACTION,target_action:ACTION,operation:OPERATION,registration_targets:['base','executor','policy','mcp'],module_count:5,services:[...SERVICES],production_application_mutation:false,database_mutation:false,titan_cutover:false,rollback:'exact-preimage'});}
function main(argv=process.argv.slice(2)){
  if(argv.length!==1||!['--selftest-only','--preflight-only','--apply'].includes(argv[0]))fail('unexpected_arguments');
  const out=argv[0]==='--selftest-only'?selftest():argv[0]==='--preflight-only'?preflight():apply();
  process.stdout.write(JSON.stringify(out)+'\n');return out;
}
module.exports=Object.freeze({ACTION,OPERATION,INSTALLER_ACTION,VERSION,LIVE_PINS,TARGETS,PRIVATE_DIR,ACTION_PATH,BACKUP_ROOT,RESULT,SERVICES,MODULE_INSTALLS,EXECUTOR_SYSTEMD_PROPERTIES,buildPolicyRegistration,buildTypedScope,buildBaseRegistration,buildExecutorRegistration,buildMcpRegistration,buildPolicySourceRegistration,buildRegistrationCandidates,embeddedModules,selftest,preflight,apply,contract,main});
if(require.main===module){try{main();}catch(error){console.error(JSON.stringify({ok:false,action:INSTALLER_ACTION,error:String(error&&error.message||error)}));process.exit(1);}}
